// План specs/modals.md, 1.1 (кейс MD-01). Admin, компания «test». Только чтение: окно закрывается Esc, клиент не выбирается. @prod-safe
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, DEVICES, closeWithEsc, expectOpaqueModalOverDimmedPage, openCreateNew } from './modal-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Модальные окна — непрозрачный фон (#08737d6c)', () => {
  for (const device of DEVICES) {
    test(`Select Client in New Estimate is opaque over a dimmed page #08737d6c ${device} @prod-safe`, async ({ page }, testInfo) => {
      // Шаг 1: Create new → New Estimate
      await openCreateNew(page, testInfo);
      await page.getByText('New Estimate', { exact: true }).filter({ visible: true }).first().click();
      await page.waitForURL(/\/EstimateCreation/);

      // Шаг 2: открылось «Select Client» — непрозрачное, страница затемнена
      const dialog = page.getByRole('dialog', { name: 'Select Client' });
      await expectOpaqueModalOverDimmedPage(page, dialog);
      await expect(dialog.getByText('Choose a client to create an estimate for')).toBeVisible();
      await expect(dialog.getByRole('button', { name: 'New Client' })).toBeVisible();

      // Шаг 3: Esc закрывает окно и затемнение
      await closeWithEsc(page, dialog);
    });
  }
});
